cd /tmp/fceval-m1-t1-1v54emg9/work/.firecrawl; firecrawl scrape "https://www.snowflake.com/en/customers/all-customers/" >/dev/null 2>&1; cat > /tmp/fceval-m1-t1-1v54emg9/s3.js <<'EOF'
await page.getByText('Financial Services',{exact:true}).first().click();
await page.waitForTimeout(2500);
const out = {};
const grab = async () => page.evaluate(()=>[...document.querySelectorAll('a[href*="/customers/all-customers/"]')].filter(a=>/\/(case-study|video|snapshot)\//.test(a.href)).map(a=>a.href+' | '+a.innerText.replace(/\s+/g,' ').trim()));
let pageNo=1;
while(pageNo<20){
  const items = await grab();
  items.forEach(i=>out[i.split(' | ')[0]]=i);
  const next = page.getByText('Next',{exact:true}).first();
  const before = items.join();
  if(!(await next.isVisible().catch(()=>false))) break;
  await next.click({timeout:3000}).catch(()=>{});
  await page.waitForTimeout(1500);
  if((await grab()).join()===before) break;
  pageNo++;
}
console.log('PAGES',pageNo, 'N', Object.keys(out).length);
console.log(Object.values(out).join('\n'));
EOF
firecrawl interact --node --timeout 200 -c "$(cat /tmp/fceval-m1-t1-1v54emg9/s3.js)" -o sffs.txt 2>&1 | tail -2; grep -c . sffs.txt; head -3 sffs.txt | cut -c1-200; grep PAGES sffs.txt

